public class SeatBooking {static class Booking{int seats=5,success=0;boolean book(){if(seats>0){Thread.yield();seats--;success++;return true;}return false;}synchronized boolean safeBook(){if(seats>0){seats--;success++;return true;}return false;}}public static void main(String[] args)throws Exception{Booking b=new Booking();Thread[] t=new Thread[10];for(int i=0;i<10;i++){t[i]=new Thread(()->{if(b.book())System.out.println("Booked");});t[i].start();}for(Thread x:t)x.join();System.out.println("Unsynchronized success: "+b.success);b.seats=5;b.success=0;for(int i=0;i<10;i++){t[i]=new Thread(()->{if(b.safeBook())System.out.println("Safe booking");});t[i].start();}for(Thread x:t)x.join();System.out.println("Synchronized success: "+b.success);}}
